-- H2-only fixture for product content, reviews, and catalog filtering.
CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(255),slug VARCHAR(255) UNIQUE,description TEXT,is_deleted BOOLEAN DEFAULT FALSE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,category_id BIGINT,sku VARCHAR(100) UNIQUE,name VARCHAR(255),slug VARCHAR(255) UNIQUE,description TEXT,usage_instructions TEXT,cost_price NUMERIC(12,2) DEFAULT 0,list_price NUMERIC(12,2),low_stock_threshold INT DEFAULT 5,is_deleted BOOLEAN DEFAULT FALSE,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_variants(id BIGSERIAL PRIMARY KEY,product_id BIGINT,color VARCHAR(50),size VARCHAR(50),is_deleted BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS product_images(id BIGSERIAL PRIMARY KEY,product_id BIGINT,image_url VARCHAR(500),display_order INT,is_primary BOOLEAN,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_items(id BIGSERIAL PRIMARY KEY,variant_id BIGINT UNIQUE,quantity INT DEFAULT 0,reserved_quantity INT DEFAULT 0,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_holds(id BIGSERIAL PRIMARY KEY,inventory_item_id BIGINT,order_id BIGINT,quantity INT,status VARCHAR(20),expires_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS stock_movements(id BIGSERIAL PRIMARY KEY,variant_id BIGINT,movement_type VARCHAR(50),quantity INT,reference_type VARCHAR(30),reference_id BIGINT,note VARCHAR(500),created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_reviews(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL,user_id BIGINT NOT NULL,rating INT CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(2000),created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,user_id));
